#include "quake/frame3d.hpp"
#include "quake/newmark.hpp"
#include "quake/suite.hpp"
#include <algorithm>
#include <chrono>
#include <iomanip>
#include <iostream>
#include <thread>
#include <vector>
using namespace quake;
static int nid(int s,int ix,int iy){return 10000*s+100*ix+iy;}
static CompiledFrame3D make_space_frame(int stories,int nx,int ny){Frame3DBuilder b;constexpr double h=3.5,L=6.0,E=25000,G=10000;const int nc=(nx+1)*(ny+1);for(int s=0;s<=stories;++s)for(int ix=0;ix<=nx;++ix)for(int iy=0;iy<=ny;++iy){int id=nid(s,ix,iy);double m=s?1.0/nc:0;b.add_node(id,ix*L,iy*L,s*h,m,m,0.05*m);if(!s)b.fix(id);}int eid=1,sid=1,did=500000;for(int s=1;s<=stories;++s){double p=6.0*(stories-s+1);for(int ix=0;ix<=nx;++ix)for(int iy=0;iy<=ny;++iy)b.add_elastic_frame(eid++,nid(s-1,ix,iy),nid(s,ix,iy),E,G,2,.3,.55,.55,1,0,0,p);for(int ix=0;ix<nx;++ix)for(int iy=0;iy<=ny;++iy){int jl=nid(s,ix,iy),jr=nid(s,ix+1,iy),dl=did++,dr=did++;b.add_node(dl,ix*L,iy*L,s*h);b.add_node(dr,(ix+1)*L,iy*L,s*h);for(auto d:{Dof3D::UX,Dof3D::UY,Dof3D::UZ,Dof3D::RX,Dof3D::RZ}){b.equal_dof(jl,dl,d);b.equal_dof(jr,dr,d);}b.add_elastic_frame(eid++,dl,dr,E,G,1.5,.2,.35,.35,0,1,0);b.add_bilinear_spring(sid++,jl,Dof3D::RY,dl,Dof3D::RY,50000,8,.5);b.add_bilinear_spring(sid++,jr,Dof3D::RY,dr,Dof3D::RY,50000,8,.5);}for(int ix=0;ix<=nx;++ix)for(int iy=0;iy<ny;++iy){int jl=nid(s,ix,iy),jr=nid(s,ix,iy+1),dl=did++,dr=did++;b.add_node(dl,ix*L,iy*L,s*h);b.add_node(dr,ix*L,(iy+1)*L,s*h);for(auto d:{Dof3D::UX,Dof3D::UY,Dof3D::UZ,Dof3D::RY,Dof3D::RZ}){b.equal_dof(jl,dl,d);b.equal_dof(jr,dr,d);}b.add_elastic_frame(eid++,dl,dr,E,G,1.5,.2,.35,.35,1,0,0);b.add_bilinear_spring(sid++,jl,Dof3D::RX,dl,Dof3D::RX,50000,8,.5);b.add_bilinear_spring(sid++,jr,Dof3D::RX,dr,Dof3D::RX,50000,8,.5);}}b.set_rayleigh(.02,.0005);b.set_ground_direction(Dof3D::UX);b.set_response(nid(stories,0,0),Dof3D::UX);std::vector<int> sn;for(int s=1;s<=stories;++s)sn.push_back(nid(s,0,0));b.set_story_nodes(std::move(sn),Dof3D::UX);return b.compile();}
int main(int argc,char**argv){int stories=argc>1?std::stoi(argv[1]):10,records=argc>2?std::stoi(argv[2]):8,steps=argc>3?std::stoi(argv[3]):300,workers=argc>4?std::stoi(argv[4]):4;constexpr double dt=.005;auto model=make_space_frame(stories,2,2);std::vector<std::vector<double>> motions;for(int r=0;r<records;++r)motions.push_back(synthetic_ground_motion(steps,dt,3.0+0.5*r));PreparedWoodburyNewmark prepared(model,dt);const auto st=std::chrono::steady_clock::now();std::size_t it=0;for(auto&g:motions){auto x=prepared.run(g,1e-8,35);it+=x.stats.newton_iterations;}double seq=prepared.setup_seconds()+std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count();auto par=run_record_suite_parallel(model,motions,dt,workers,1e-8,35);std::cout<<std::fixed<<std::setprecision(6)<<"dof="<<model.dof()<<" nonlinear="<<model.nonlinear_count()<<" records="<<records<<" workers="<<par.workers<<" sequential_s="<<seq<<" parallel_s="<<par.elapsed_seconds<<" parallel_speedup="<<seq/par.elapsed_seconds<<" newton_iters="<<it<<"\n";}
